import{_ as r,o as t,c as i,ag as o}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Release","description":"","frontmatter":{},"headers":[],"relativePath":"release/index.md","filePath":"release/index.md"}'),a={name:"release/index.md"};function s(d,e,n,c,l,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="release" tabindex="-1">Release <a class="header-anchor" href="#release" aria-label="Permalink to &quot;Release&quot;">​</a></h1><h2 id="published-provider-and-retained-provider-history" tabindex="-1">Published Provider and retained Provider history <a class="header-anchor" href="#published-provider-and-retained-provider-history" aria-label="Permalink to &quot;Published Provider and retained Provider history&quot;">​</a></h2><p>Provider <strong>v4.0.0</strong> is the current Registry-published Terraform/OpenTofu Provider at the <code>tako0614/takoform</code> address. It selects only the 17 exact Edge Forms selected from the <code>tako0614/takoform-forms</code> set tag <code>forms/sets/e7f8a39311dd011b8467e97e7f300cabb9a6b06c</code> — the 16 Edge Forms carried over from Provider 3 plus <code>ObjectBucket</code>. Its signed tag, immutable GitHub Release, and Registry readback are the <code>4.0.0</code> entry of the identity ledger below. The 15 removed aggregate types and explicit state paths are documented in <a href="./migrations/v3-to-v4.html">v3 to v4 publisher-set migration</a>. Ordinary AWS, Cloudflare, Kubernetes, and other resources remain native resources of their own providers. Why the publisher set is the released roster is recorded in <a href="https://github.com/tako0614/takos-control/blob/main/docs/platform/decisions/0020-provider-4-is-the-publisher-set-release.md" target="_blank" rel="noreferrer">control ADR 0020</a>, which also states why this repository&#39;s own decision series cannot take that entry while the Specification 1.1 receipt seals <code>spec/</code>.</p><p>Provider <strong>v3.0.0</strong> is retained Registry history at the same address. Its immutable release registers 31 typed resources across eight versionless families; each resource keeps an exact FormRef and provider mapping in its release identity projection. Provider release, Form Definition publication, package publication, and Host deployment are separate owner actions.</p><p><code>release/version.json</code> is the Provider <code>4.0.0</code> release descriptor every release entrypoint reads; it keeps <code>publicationStatus: candidate-only</code> by the standing descriptor convention and is not live publication state. The Registry readback recorded in the identity ledger is the availability authority. <code>release/candidates/provider-v4.0.0.json</code> is the retained candidate record and stays byte-identical to it, with its derived 17-Form mapping in <code>release/candidates/provider-v4.0.0-form-identities.json</code>. <code>release/history/provider-v3.0.0.json</code> is the retained Provider 3 writer input. It and the immutable Provider 3 identity ledger entry remain byte-stable history; neither is reused to publish Provider 4.</p><p>The Provider 4 production binary embeds only that publisher closure: 17 Form Packages, their eight exact Interface definitions, and seven exact Binding definitions. The complete Provider 3 artifact projection remains tracked as source-side immutable history for goldens and migration verification; it is no longer bundled into the current provider binary.</p><p>The signed release-tag commit must be an ancestor of the reviewed protected-main/readback commit used for the release.</p><p>The release identity and Registry readback are recorded in the <a href="https://github.com/tako0614/terraform-provider-takoform/blob/main/release/provider-release-identities.json" target="_blank" rel="noreferrer">Provider release identity ledger</a>. The <a href="./../docs/">Provider reference</a> contains the install pin and generated resource contracts.</p><h2 id="compatibility-and-migration" tabindex="-1">Compatibility and migration <a class="header-anchor" href="#compatibility-and-migration" aria-label="Permalink to &quot;Compatibility and migration&quot;">​</a></h2><h3 id="provider-3-to-provider-4" tabindex="-1">Provider 3 to Provider 4 <a class="header-anchor" href="#provider-3-to-provider-4" aria-label="Permalink to &quot;Provider 3 to Provider 4&quot;">​</a></h3><p>Provider 3.0.0 is the compatibility predecessor of Provider 4 and remains installable. The exact removal and state boundary is <a href="./migrations/v3-to-v4.html">v3 to v4 publisher-set migration</a>; a consumer may instead stay pinned to <code>= 3.0.0</code> as retained history.</p><h3 id="retained-v1beta1-history-provider-2-1-1" tabindex="-1">Retained v1beta1 history (Provider 2.1.1) <a class="header-anchor" href="#retained-v1beta1-history-provider-2-1-1" aria-label="Permalink to &quot;Retained v1beta1 history (Provider 2.1.1)&quot;">​</a></h3><p>Provider 2.1.1 remains the retained v1beta1 compatibility predecessor of Provider 3. Its identity ledger retains 15 exact v1beta1 Form identities; 14 remain readable by Provider 3 state/import dispatch. ObjectBucket has no Provider 3 resource or codec, so ObjectBucket state carried across the Provider 2 to Provider 3 boundary needs explicit pre-upgrade handling; the Provider 4 publisher set does select <code>ObjectBucket</code>. Existing Provider 2 state needs an explicit cutover; follow <a href="./migrations/v2-to-v3.html">v2 to v3 migration</a> before changing the required provider version. Provider 3 does not rewrite Provider 1 state; the <a href="./migrations/v1-to-v2.html">v1 to v2 migration</a> is the earlier boundary.</p><p>The Provider 4 publisher mapping group is <code>edge.forms.takoform.com</code> and uses <code>packages.forms.takoform.com/v1alpha5</code>. Retained Provider 2.1.1 history uses Host API <code>forms.takoform.com/v1beta1</code>, family <code>edge.forms.takoform.com/v1beta1</code>, and package envelope <code>packages.forms.takoform.com/v1alpha4</code>.</p><p>The <a href="https://github.com/tako0614/terraform-provider-takoform/blob/main/website/docs/versions.md" target="_blank" rel="noreferrer">versions page</a> lists the current API/Core checkpoint, Provider releases, package publication, and retained history in one place.</p><h2 id="core-and-specification-history" tabindex="-1">Core and Specification history <a class="header-anchor" href="#core-and-specification-history" aria-label="Permalink to &quot;Core and Specification history&quot;">​</a></h2><p>The current Core/API checkpoint is <a href="https://github.com/tako0614/takoform/tree/v1.0.1/spec" target="_blank" rel="noreferrer">Core v1.0.1</a> on <code>forms.takoform.com/v1</code>. Specification 1.1 is retained as an immutable historical source receipt.</p><p>Release tooling and ledgers are maintained in the <a href="https://github.com/tako0614/terraform-provider-takoform/tree/main/release" target="_blank" rel="noreferrer">Provider repository</a>. They provide Provider provenance and migration evidence.</p>',18)])])}const v=r(a,[["render",s]]);export{m as __pageData,v as default};
